<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $from = "2026-07-03"; $item_id = DB::table("stock_movements")->select("item_id")->groupBy("item_id")->orderByRaw("COUNT(*) DESC")->first()->item_id; $res = DB::table("stock_movements")->select(DB::raw("SUM(qty_in) - SUM(qty_out) as net_qty"))->where("item_id", $item_id)->whereDate("moved_at", "<", $from)->value("net_qty"); echo "Opening Stock: $res\n";
